public sealed class Product
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    [Timestamp] public byte[] RowVersion { get; set; } = [];   // EF Core concurrency token
}

app.MapPut("/products/{id}", async (string id, UpdateProductRequest request, HttpRequest http, AppDbContext db, CancellationToken ct) =>
{
    if (!http.Headers.TryGetValue("If-Match", out var ifMatch)) return Results.StatusCode(428);

    var product = await db.Products.FindAsync([id], ct);
    if (product is null) return Results.NotFound();

    // Tell EF which version the client saw; SaveChanges adds "WHERE RowVersion = @original".
    db.Entry(product).Property(p => p.RowVersion).OriginalValue = ETags.Parse(ifMatch!);
    product.Name = request.Name.Trim();

    try { await db.SaveChangesAsync(ct); }
    catch (DbUpdateConcurrencyException) { return Results.StatusCode(412); }

    http.HttpContext.Response.Headers.ETag = ETags.Format(product.RowVersion);
    return Results.Ok(product.ToDto());
});

var key = http.Headers["Idempotency-Key"].ToString();
var saved = await db.IdempotencyRecords.FindAsync([key], ct);
if (saved is not null)
{
    return saved.RequestHash == Hash(request)
        ? Results.Json(saved.ResponseBody, statusCode: saved.StatusCode)   // replay, create nothing
        : Results.UnprocessableEntity();                                   // key reused for a different request
}

var order = Order.Create(request);
db.Orders.Add(order);
db.IdempotencyRecords.Add(new IdempotencyRecord(key, Hash(request), 201, order.ToDto()));
await db.SaveChangesAsync(ct);   // one transaction: the order and its key commit together
